public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] args = pt.getActualTypeArguments();
    Class<?>[] resolved = new Class<?>[args.length];
    Map<String, Type> typeVarMap = buildTypeVarMap(targetType);
    for (int i=0; i<args.length; i++) {
        Type arg = args[i];
        if (arg instanceof Class<?>) {
            resolved[i] = (Class<?>) arg;
        } else if (arg instanceof ParameterizedType) {
            Type raw = ((ParameterizedType) arg).getRawType();
            if (raw instanceof Class<?>) {
                resolved[i] = (Class<?>) raw;
            } else {
                resolved[i] = null;
            }
        } else if (arg instanceof TypeVariable<?>) {
            Type mapped = typeVarMap.get(((TypeVariable<?>) arg).getName());
            if (mapped instanceof Class<?>) {
                resolved[i] = (Class<?>) mapped;
            } else if (mapped instanceof ParameterizedType) {
                resolved[i] = (Class<?>) ((ParameterizedType) mapped).getRawType();
            } else {
                resolved[i] = null;
            }
        } else if (arg instanceof WildcardType) {
            resolved[i] = null;
        } else {
            resolved[i] = null;
        }
    }
    return resolved;
}

