public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength <= 0) {
        return this;
    }
    int required = this.size + byteLength;
    if (required > this.buffer.length) {
        int newSize = Math.max(this.buffer.length * 2, required);
        byte[] newBuffer = new byte[newSize];
        System.arraycopy(this.buffer, 0, newBuffer, 0, this.size);
        this.buffer = newBuffer;
    }
    if (byteArrayValue == null) {
        for (int i = 0; i < byteLength; i++) {
            this.buffer[this.size + i] = 0;
        }
    } else {
        System.arraycopy(byteArrayValue, byteOffset, this.buffer, this.size, byteLength);
    }
    this.size += byteLength;
    return this;
